package school.magiccodex.client;
import java.io.*;import java.nio.file.*;import java.util.*;
/** GUI-scaled coordinates are persisted as normalized free-space anchors, never raw pixels. */
public final class HudLayoutStore {
 public record Box(float x,float y,float width,float height){public boolean contains(double px,double py){return px>=x&&py>=y&&px<=x+width&&py<=y+height;}}
 public record Placement(float x,float y,float scale){}
 private final Map<String,Placement> entries=new HashMap<>();private boolean locked=true;
 public boolean locked(){return locked;}public void locked(boolean value){locked=value;}
 private static float clamp(float v,float a,float b){return Float.isFinite(v)?Math.max(a,Math.min(b,v)):a;}
 public Placement value(String id){return entries.get(id);}
 public void reset(String id){entries.remove(id);}public void reset(){entries.clear();}
 public Box fit(String id,Box base,int width,int height){var p=entries.get(id);float scale=p==null?1:p.scale;scale=Math.min(scale,Math.min(width/Math.max(1,base.width),height/Math.max(1,base.height)));float w=Math.max(1,base.width*scale),h=Math.max(1,base.height*scale);float x=p==null?clamp(base.x,0,width-w):p.x*Math.max(0,width-w),y=p==null?clamp(base.y,0,height-h):p.y*Math.max(0,height-h);return new Box(x,y,w,h);}
 public void place(String id,Box base,int width,int height,float x,float y,float scale){if(!id.matches("[a-z0-9_-]{1,48}"))throw new IllegalArgumentException("HUD ID");scale=clamp(scale,.4f,2.5f);scale=Math.min(scale,Math.min(width/Math.max(1,base.width),height/Math.max(1,base.height)));entries.put(id,new Placement(clamp(x/Math.max(1,width-base.width*scale),0,1),clamp(y/Math.max(1,height-base.height*scale),0,1),scale));}
 public static HudLayoutStore load(Path file){var s=new HudLayoutStore();if(!Files.isRegularFile(file))return s;var p=new Properties();try(var in=Files.newBufferedReader(file)){p.load(in);s.locked=!"false".equals(p.getProperty("locked"));for(String k:p.stringPropertyNames())if(k.endsWith(".scale")){String id=k.substring(0,k.length()-6);if(!id.matches("[a-z0-9_-]{1,48}"))continue;try{float x=Float.parseFloat(p.getProperty(id+".x")),y=Float.parseFloat(p.getProperty(id+".y")),z=Float.parseFloat(p.getProperty(k));if(Float.isFinite(x)&&Float.isFinite(y)&&Float.isFinite(z))s.entries.put(id,new Placement(clamp(x,0,1),clamp(y,0,1),clamp(z,.4f,2.5f)));}catch(RuntimeException ignored){}}}catch(IOException|IllegalArgumentException ignored){}return s;}
 public boolean save(Path file){Path tmp=null;try{Path target=file.toAbsolutePath();Files.createDirectories(target.getParent());tmp=Files.createTempFile(target.getParent(),"hud-layout-",".tmp");var p=new Properties();p.setProperty("locked",Boolean.toString(locked));for(var e:entries.entrySet()){p.setProperty(e.getKey()+".x",Float.toString(e.getValue().x));p.setProperty(e.getKey()+".y",Float.toString(e.getValue().y));p.setProperty(e.getKey()+".scale",Float.toString(e.getValue().scale));}try(var out=Files.newBufferedWriter(tmp)){p.store(out,"HUD layout only; chat and full Screen windows excluded");}try{Files.move(tmp,target,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,target,StandardCopyOption.REPLACE_EXISTING);}return true;}catch(IOException e){return false;}finally{if(tmp!=null)try{Files.deleteIfExists(tmp);}catch(IOException ignored){}}}
}
